/* 植物病毒分析平台 · 前端多语言运行时（zh / en）
 * 用法：
 *   1) 模板元素加 data-i18n="key"（textContent/innerHTML）、
 *      data-i18n-ph="key"（placeholder）、data-i18n-title="key"（title）
 *   2) JS 动态文案用 t('key', '回退文案')
 *   3) 当前语言：<meta name="vp-lang"> 由服务端按 platform.json 输出；
 *      切换语言 POST /api/settings 后刷新，前后端文案一致。
 */
