    'rd.hostTitle': '🧬 Host genome download (→ build host DB)',
    'rd.hostHint': 'Host removal (tool ①) and host prediction (tool ④) both need a host DB. Three sources: gget·Ensembl (covers plant hosts such as rice, tomato, wheat that NCBI lacks), NCBI taxon (by species), NCBI accession (precise by assembly, with chromosome filter). Output goes to host-db/<TaxID>_<species>/genome.fa — after download, click "Build host DB" on the DB-building page (path and TaxID resolved automatically). gget needs pip install "gget==0.30.5"; accession mode needs the datasets CLI (python main.py datasets-setup). NCBI source without an accession queries first, then downloads: a single assembly is picked automatically; multiple versions are listed for you to choose — never a blind download.',
    'rd.virusTitle': '🦠 NCBI datasets virus dataset (→ virus DB building)',
    'rd.virusHint': 'Fetch NCBI virus genomes by taxon (optionally filtered by host), auto-producing reference.fasta + reference.ref_info.tsv (with Taxid/host/geography columns) under databases/virusref_db/<name>/ — recognized immediately by the "Raw datasets" card on the DB-building page for one-click index or kunpeng DB building. Requires the NCBI datasets CLI (auto-install with python main.py datasets-setup if missing). Tip: click "🔍 Query matching sequences" before downloading to preview the hits; you can also download a single accession right from the query table.',
    'rd.goBuild': 'Go to DB building page →',
    'rd.goHostBuild': 'Go build host DB →',
    'rd.genTitle': '📥 NCBI datasets generic download (genome / gene / taxonomy)',
    'rd.genHint': 'Remaining datasets CLI modes: genome packages for any species (taxon / accession + chromosome filter), gene packages (gene-id / symbol+taxon / protein accession), taxonomy report packages. Output lands in datasets_dl/ for downstream annotation, alignment and tree building. Legacy --exclude-* flags are auto-translated to --include combinations. Tip: click "🔍 Query preview" before downloading to check the matched records (genome query rows can fill in the accession directly).',
