    'bd.seqName': '⚙ kunpeng sequence-name requirements (source-level; a missing taxid aborts the build)',
    'bd.seqNameHint': 'When building or supplying a library yourself, every FASTA header must look like <code>&gt;taxid|12345|any_seqid optional description</code>: the taxid segment must appear before the first whitespace, the key must be lowercase taxid (kraken:taxid also works; TAXID does not), and the value must be all digits. <code>&gt;seqid|taxid|12345</code> and <code>&gt;seqid|kraken:taxid|12345</code> are equally valid. As long as the header carries a taxid you do not need to supply a seqid2taxid map; kunpeng generates it. The built-in RefSeq/RVDB flows and host-DB builds inject taxids automatically, so this format never concerns you there.',
