  'tk.kvHint': 'Map sample reads <b>directly against the known-virus reference</b>. This card runs two stages only: <b>identification/quantification</b> (alignment + coverage + Poisson false-positive test) → <b>filtering</b> (dual-track threshold review).<br>Consensus, depth plots and variant annotation belong to <b>downstream modules</b> (“Consensus &amp; variants”, “Variant analysis”) or to the “⚡ one-click full pipeline” — this card neither does them nor offers switches for them.<br>Two quantification engines (orthogonal to the DB choice; a missing index is built in the run directory on the fly): <b>salmon</b> = EM quantification (probabilistic multi-mapping, more sensitive, default); <b>minibwa</b> = true-alignment counts. The consensus stage always uses its own internal minibwa regardless of this choice.<br>Outputs: <b>identify/all_viruses.summary.tsv</b>, <b>filter/filtered.tsv</b>, the alignment <b>BAM</b>.',
