  'tk.mirH2': '🧬 miRNA target prediction (PAmiRDB)',
  'tk.mirDesc': 'PAmiRDB engines ported: input miRNA and virus sequences; Smith-Waterman alignment (seed 2-8 fully paired) is the base, then the engines you tick vote in the consensus (miRanda + psRNATarget + RNAhybrid ticked by default; RNA22 / TAPIR / psRobot optional). Outputs binding sites, colored alignment, seed quality, duplex SVG and miRNA secondary-structure arc. Pure Python, no external dependencies; virus sequences over 15 kb are truncated (same as the PAmiRDB v7 pipeline).',
