    'rs.archiveHint': 'Archived samples are hidden from module dropdowns and the home page recent list; to restore, move the directory from results/_archive/ back to results/.',
    'rs.mmTitle': '🔎 Public search projects (SRA + GSA)',
    'rs.mmHint': 'Every search on the Public data search page is archived as a standalone project (dual storage: search results + Core14 metadata). View / preview / download / delete here; click Open search page to keep editing with AI completion.',
    'rs.runsHint': 'Records and artifacts of all specialized tool runs are kept here (30 most recent). Click a filename to download; contig classification runs open an interactive report (Sankey / sunburst / classification table).',
    'lg.intro': 'Submit identified viral sequences to <b>Logan-Search</b> (logan-search.org; a k-mer index of all NCBI SRA assemblies, covering ~23.4 million public samples) to answer in <b>which species and samples</b> the virus truly occurs, cross-validated with the platform ④ ICTV host prediction. Supports <b>one-click batch auto-submission</b> and <b>manual semi-automatic</b> modes.',
    'lg.flowTip': 'Mode 1 · one-click batch | Mode 2 · manual semi-automatic (click title to collapse/expand)',
    'lg.modeANote': 'Requires selenium (pip install selenium) and a local Edge/Chrome',
    'lg.stepA1': 'Create a query below: pick the sample viral contigs (or paste sequences); the platform splits them into ≤2.5 kb query fragments.',
    'lg.stepA2': 'In the job card, fill in the <b>notification email</b>, choose Groups, then click One-click batch submit. The platform opens the local browser, submits each fragment, polls for results, downloads the result tables and <b>auto-imports them to build the report</b>; no babysitting required.',
    'lg.stepA3': 'A few fragments not settled due to timeout? <b>Click batch submit once more to fill the gaps</b> (already-downloaded fragments are skipped automatically).',
    'lg.modeBNote': 'Works without installing selenium',
    'lg.stepB1': 'For each fragment click Copy sequence → click Open Logan-Search and paste to submit. Recommended Groups: <b>All_No_viral_human</b> (use Fast for a quick pre-check), Threshold defaults to 0.25; <b>providing an email</b> is recommended to get the result download link.',
    'lg.stepB2': 'Download the result table (CSV/TSV) locally, then click Import result on the corresponding fragment.',
  'tk.b.summaryDir': 'Summary directory (symlinks)',
  'tk.csH2': '🧬 Consensus sequence and variant analysis',
  'tk.csHint': 'Map reads <b>back to the verified candidate contigs</b> to produce a <b>refined consensus sequence</b> and a <b>variant profile</b>.\n       The approach follows MultiVirusConsensus (parallel multiple references + coverage-based presence calls),\n       but relies only on <b>minimap2</b>: consensus calling is rewritten in Python, so samtools / viral_consensus\n       are not required (neither has official Windows builds).<br>\n       Outputs: <b>consensus.fa</b> (consensus sequence), <b>poscounts.tsv</b> (per-base counts),\n       <b>inscounts.json</b> (insertions), <b>variants.tsv</b> (variant sites), <b>coverage.tsv</b> (coverage stats).',
