  'tk.vrH2': '🧬 Viral variant analysis',
  'tk.vrHint': 'Provide a <b>BAM alignment</b> or a <b>VCF variant file</b>, then run <b>bcftools caller (optional)</b>\n       → <b>SnpEff 5.4c functional annotation</b> → <b>8 variant plots</b> (four basic + four extended)\n       + <b>SNPGenie dN/dS</b>. Chained to the upstream “Known virus identification and quantification”: <b>leave both inputs empty</b>\n       to use the <span class="mono">kvsuite/bam</span> of the most recent run.<br>\n       Outputs: <span class="mono">variant_plots/&lt;ref&gt;_variant_{map,effect,af_dp,overview}.{png,pdf}</span>,\n       <span class="mono">&lt;ref&gt;_evo_{spectrum,landscape,density,popgen,snpgenie}</span>,\n       <span class="mono">variant_evo/&lt;ref&gt;.snpgenie/</span>.',
