  'tk.homH2': '🎯 Homology search (BLASTN · BLASTX)',
  'tk.homHint': 'Run <b>BLASTN / BLASTX</b> homology search on each viral contig\n       (NCBI nt / nr, viruses only), providing the basis for GenBank submission annotation. Results are cached under the run\'s\n       analysis/ directory for repeat viewing; the hit table follows the Metabuli style (accessions link back to\n       NCBI, identity is binned by colour). Note: identity bins only reflect the nearest homology level;\n       for formal species demarcation use SDT in the “Comparative genomics” group. For <b>primer design</b> use the standalone module\n       “<a href="/primer">🧪 Primer design (primer3)</a>”.',
  'tk.seqprepH2': '🧬 Reference sequence retrieval (ICTV family / genus · accession · query)',
  'tk.seqprepHint': 'Sequence preparation for comparative genomics: one-click download of whole-family or whole-genus\n       reference genomes by <b>ICTV family / genus</b> (databases/tree_db/ictv_tree.db lineage + local sequences first, gaps filled from NCBI),\n       or download by accession list / Entrez query. Each download produces both:\n       a <b>GenBank collection</b> (CDS annotations retained → phylogenetic tree building) and\n       a <b>FASTA reference set</b> (extra references for sample-pipeline tree building); importing local .gb/.gbk is also supported.',
