  'cd.hint': 'Standalone module: parses every GenBank record in the collection and lists each CDS grouped by virus with\n       gene name / product / start / end / length; tick the CDS you need (double-click a gene name to rename),\n       review the summary on the right, then “📤 Export”. CDS sharing the same name go into one file.\n       Products land in the collection\'s <code>extract/selected/</code>: <code>CDS.fa</code> / <code>PEP.fa</code> (combined),\n       <code>CDS/&lt;gene&gt;.fa</code> and <code>PEP/&lt;gene&gt;.fa</code> (grouped by gene name).',
