  'tk.tbH2': '🌳 Phylogenetic tree construction (family / genus level)',
  'tk.tbHint': 'Three steps for family/genus tree building: ① download a GenBank collection from the "Reference retrieval" card → ② select the collection on this card to build a tree (whole-genome MAFFT alignment + trimAl trimming + NJ / FastTree / RAxML-NG; RAxML-NG yields an ML tree with FBP bootstrap support values) → ③ view the tree in-page; products are viewed/exported as "🧬 Collection" in the Results Center. To inspect the alignment itself, use the alignment viewer on the "🧬 Sequence alignment" card (this card has a jump button). You can also build a tree directly from FASTA input.',
